std::wstring iniPath(){wchar_t path[32768];auto length=GetEnvironmentVariableW(L"LOCALAPPDATA",path,32768);std::wstring directory=length?std::wstring(path):executableDir();directory+=L"\\BES";if(!preview)CreateDirectoryW(directory.c_str(),nullptr);return directory+L"\\settings.ini";}
void save(){if(preview)return;auto path=iniPath();WritePrivateProfileStringW(L"BES",L"audioProfileVersion",L"4",path.c_str());WritePrivateProfileStringW(L"BES",L"name",read(nameEdit).c_str(),path.c_str());WritePrivateProfileStringW(L"BES",L"ptt",voice.pushToTalk?L"1":L"0",path.c_str());for(auto item:{std::pair<LPCWSTR,HWND>{L"key",keyCombo},{L"gate",gateCombo},{L"volume",volCombo},{L"noise",noiseCombo}})WritePrivateProfileStringW(L"BES",item.first,std::to_wstring(selected(item.second)).c_str(),path.c_str());WritePrivateProfileStringW(L"BES",L"microphone",read(micCombo).c_str(),path.c_str());WritePrivateProfileStringW(L"BES",L"speaker",read(outCombo).c_str(),path.c_str());}
void showTray(bool show){NOTIFYICONDATAW item{};item.cbSize=sizeof item;item.hWnd=window;item.uID=1;item.uFlags=NIF_MESSAGE|NIF_ICON|NIF_TIP;item.uCallbackMessage=WM_APP+1;item.hIcon=LoadIconW(GetModuleHandleW(nullptr),MAKEINTRESOURCEW(1));wcscpy_s(item.szTip,L"BES — достарыңның дауысы");if(show&&!tray){Shell_NotifyIconW(NIM_ADD,&item);tray=true;}if(!show&&tray){Shell_NotifyIconW(NIM_DELETE,&item);tray=false;}}
void syncSettings(){int keys[]={VK_XBUTTON1,VK_XBUTTON2,VK_LMENU,'V'},gates[]={0,65,100,220,400},volumes[]={25,50,75,100,125,150};voice.pttKey=keys[std::clamp(selected(keyCombo),0,3)];voice.gate=gates[std::clamp(selected(gateCombo),0,4)];voice.volume=volumes[std::clamp(selected(volCombo),0,5)];voice.noiseMode=std::clamp(selected(noiseCombo),0,2);save();}
std::wstring roomStore(){auto path=iniPath();return path.substr(0,path.find_last_of(L"\\"))+L"\\room.bin";}
void loadRoom(){if(preview)return;room=readPortableProfile(executableDir()+L"\\BES-room.ini");if(!room.valid())room=readEmbeddedProfile();if(room.valid())saveProtectedProfile(roomStore(),room);else room=readProtectedProfile(roomStore());}
void applyConnection(){if(preview||!room.valid())return;auto nick=read(nameEdit);if(nick.empty()||nick.size()>32||utf8(nick).size()>80)return;for(auto c:nick)if(c<32||c==127)return;unsigned in=selected(micCombo)>0?selected(micCombo)-1:WAVE_MAPPER,out=selected(outCombo)>0?selected(outCombo)-1:WAVE_MAPPER;save();automatic.configure(room,nick,in,out);}
void connect(){if(preview)return;if(!room.valid()){MessageBoxW(window,L"Сервері алдын ала бапталған BES жинағын пайдаланыңыз.",L"Бөлме баптауы қажет",MB_OK|MB_ICONINFORMATION);return;}if(automatic.isEnabled())automatic.setEnabled(false);else applyConnection();write(connectBtn,automatic.isEnabled()?L"Байланысты тоқтату":L"Бөлмеге қосылу");InvalidateRect(window,nullptr,FALSE);}
