 case WM_COMMAND:{int id=LOWORD(wp),notification=HIWORD(wp);if(id==CONNECT)connect();else if(id==MUTE){voice.muted=!voice.muted;write(muteBtn,voice.muted?L"Микрофон өшірулі":L"Микрофон қосулы");}else if(id==DEAFEN){voice.deafened=!voice.deafened;write(deafenBtn,voice.deafened?L"Тыңдау өшірулі":L"Тыңдау қосулы");}else if(id==PTT){voice.pushToTalk=!voice.pushToTalk;write(pttBtn,voice.pushToTalk?L"Қосулы":L"Өшірулі");save();}else if(id>=PEER&&id<PEER+5){int index=id-PEER,values[]={0,50,75,100,125,150},next=0;for(int i=0;i<6;i++)if(values[i]==voice.peerVolume[index])next=(i+1)%6;voice.peerVolume[index]=values[next];updatePeers();}else if((id==KEY||id==GATE||id==VOLUME||id==NOISE)&&notification==CBN_SELCHANGE)syncSettings();else if((id==MIC||id==OUTPUT)&&notification==CBN_SELCHANGE&&automatic.isEnabled())applyConnection();else if(id==NAME&&notification==EN_KILLFOCUS){if(automatic.isEnabled())applyConnection();else save();}InvalidateRect(hwnd,nullptr,FALSE);return 0;}
